        Action<Action,string> reject=(f,label)=>{bool bad=false;try{f();}catch(Exception e)when(e is ArgumentException || e is InvalidOperationException){bad=true;}check(bad,label);};
        var save=fresh();string form="heroine.slayer";var a=AffectionService.State(save,home,form);a.exp=95;AffectionService.Add(a,108,save.affection);check(a.level==2 && a.exp==3,"AF-01 EXP100 levels up and carries excess");
        a.level=9;a.exp=99;AffectionService.Add(a,1,save.affection);check(a.level==10 && a.exp==0 && AffectionService.IsLover(a),"AF-02 Lv10 automatically establishes lover without reading an event");
        a.level=19;a.exp=99;AffectionService.Add(a,500,save.affection);check(a.level==20 && a.exp==0,"AF-03 normal cap discards excess EXP");AffectionService.Add(a,5,save.affection);check(a.exp==0,"AF-03 capped EXP remains zero");
