        var journal=new FormalCampaignJournal(fresh(),encode,decode);FormalCampaignSave disk=null;var buy=new AffectionRequest("af.purchase",journal.Revision,"ring-purchase",Array.Empty<string>(),"ring");string before=encode(journal.Snapshot);
