        var ev=home.events.First(e=>e.heroineId==form);var replay=new AdvSession(home,ev.sceneId,ev.id,true,Array.Empty<HomeReadLine>());while(!replay.EndReached){replay.Tick(2);replay.Advance();}before=encode(shared);var replayJournal=new FormalCampaignJournal(shared,encode,decode);
        reject(()=>replayJournal.CommitAdvEnd(new FormalHomeRequest("af.replay","sceneEnd",shared.revision,home.contentVersion,ev.id+"/"+ev.sceneId+"/1"),home,replay,s=>true),"AF-08 replay cannot commit progress or rewards");check(replay.NewlyRead.Count==0 && before==encode(replayJournal.Snapshot),"AF-08 replay preserves EXP wallet read flags and campaign");
