        check(AffectionRewardService.Interaction(repeated,home,form,"together/bench.1/sit")==5 && AffectionRewardService.Interaction(repeated,home,form,"together/bench.1/sit")==3 && AffectionRewardService.Interaction(repeated,home,form,"together/bench.1/read")==5,"AF-10 furniture identity and interaction define content");
        var session=new AffectionInteractionSession("af.session",form,"conversation.a",GardenLifeCatalog.GardenIds[0],4);session.Tick(2,false);check(!session.Completed,"AF-10 inactive waiting does not complete player interaction");session.Tick(2,true);session.Cancel();session.Tick(2,true);check(session.Cancelled && !session.Completed,"AF-10 cancelled interaction never completes or grants EXP");
        journal=new FormalCampaignJournal(fresh(),encode,decode);var reward=new AffectionRequest("af.reward",journal.Revision,"interaction",new[]{form},"conversation.a");before=encode(journal.Snapshot);check(journal.CommitAffection(reward,home,s=>false)==GrowthCommitResult.SaveFailed && encode(journal.Snapshot)==before,"AF-11 reward failure publishes neither EXP nor streak");check(journal.CommitAffection(reward,home,s=>{disk=s;return true;})==GrowthCommitResult.Committed && AffectionService.State(journal.Snapshot,home,form).exp==5,"AF-11 reward retry awards once");check(new FormalCampaignJournal(disk,encode,decode).CommitAffection(reward,home,s=>throw new Exception())==GrowthCommitResult.AlreadyCommitted,"AF-11 reward replay after restart is idempotent");
        var old=fresh();old.affection=null;old.home.affections=new[]{new HomeAffection{heroineId=form,value=7},new HomeAffection{heroineId="heroine.slayer-swim",value=14},new HomeAffection{heroineId="heroine.r",value=100}};old.home.readEventIds=new[]{form+".event.0"};old.home.unlockedEventIds=old.home.readEventIds;string oldHome=JsonSerializer.Serialize(old.home,options);AffectionSaveAdapter.Migrate(old,home);
        check(AffectionService.State(old,home,form).level==14 && AffectionService.State(old,home,form).readEventIds.SequenceEqual(new[]{form+".event.0"}) && JsonSerializer.Serialize(old.home,options)==oldHome,"AF-12 maximum legacy person value and all read flags remain intact");check(AffectionService.State(old,home,"heroine.r").level==99 && AffectionService.State(old,home,"heroine.r").levelCap==99 && old.affection.legacyValues.Any(v=>v.value==100),"AF-12 out-of-range legacy original preserved with safe cap99 migration");before=encode(old);AffectionSaveAdapter.Migrate(old,home);check(before==encode(old),"AF-12 migration is idempotent");
        var many=fresh();many.affection=null;many.home=FormalHomeProgress.Empty(home.contentVersion);many.growth.heroines=Enumerable.Range(0,256).Select(i=>new FormalHeroineGrowth{heroineId="heroine.test."+i}).ToArray();AffectionSaveAdapter.Migrate(many,home);foreach(var state in many.affection.states)AffectionService.Add(state,105,many.affection);many.affection.Validate();check(many.affection.states.Length==256 && many.affection.states.All(state=>state.level==1 && state.exp==5),"AF-13 256 independent person states advance without fixed array limits");
        var max=fresh();a=AffectionService.State(max,home,form);a.level=98;a.levelCap=99;a.exp=99;AffectionService.Add(a,1,max.affection);AffectionService.Add(a,8,max.affection);check(max.affection.pendingMaxLevelPersonIds.Length==1,"AF-14 reaching Lv99 queues exactly one display");journal=new FormalCampaignJournal(max,encode,decode);var shown=new AffectionRequest("af.max",journal.Revision,"max-display",new[]{form},"max-level");check(journal.CommitAffection(shown,home,s=>false)==GrowthCommitResult.SaveFailed && journal.Snapshot.affection.pendingMaxLevelPersonIds.Length==1,"AF-14 failed milestone save leaves the display pending");check(journal.CommitAffection(shown,home,s=>true)==GrowthCommitResult.Committed && journal.Snapshot.affection.pendingMaxLevelPersonIds.Length==0 && journal.Snapshot.affection.shownMaxLevelPersonIds.Length==1,"AF-14 milestone acknowledgement is durable");max=journal.Snapshot;AffectionService.Add(AffectionService.State(max,home,form),100,max.affection);check(max.affection.pendingMaxLevelPersonIds.Length==0,"AF-14 subsequent capped rewards never repeat the display");
        var battle=fresh();var collection=ProductionStoryCatalog.Collection(combat,story);var owner=collection.owners.First(o=>WorldCatalog.ColossusIds.Contains(o.id));journal=new FormalCampaignJournal(battle,encode,decode);
        foreach(var reason in new[]{BattleEndReason.Victory,BattleEndReason.Victory,BattleEndReason.Defeat,BattleEndReason.Retreat}){
            var snap=journal.Snapshot;var collected=new BattleCollectionSession(collection,"af.battle."+snap.revision,owner.id,1,snap.revision,combat.FormationIds).Finish(reason,snap.world.poemIds,snap.world.unlockedStoryIds);var req=new FormalBattleEndRequest(collected,snap.revision);
            Func<CampaignSaveV2,CampaignSaveV2> victory=w=>{var state=new CampaignState(WorldCatalog.ColossusIds,w);state.ClaimColossusVictory(owner.id,WorldCatalog.Colossi.First(c=>c.Id==owner.id).EnvironmentTags,new VictoryReward(req.Id,1,1,1,Array.Empty<string>()),Array.Empty<StoryRequirement>(),Array.Empty<TerraformingMilestone>(),GardenCatalog.Requirements);return state.CreateSave();};
            before=encode(snap);check(journal.CommitBattleEnd(req,collection,victory,s=>false,home)==GrowthCommitResult.SaveFailed && encode(journal.Snapshot)==before,"AF-09/11 battle EXP is part of the atomic battle candidate "+reason);check(journal.CommitBattleEnd(req,null,null,s=>true)==GrowthCommitResult.Committed,"AF-09 battle result retries without duplicate affection "+reason);
        }
        check(combat.FormationIds.All(id=>AffectionService.State(journal.Snapshot,home,id).exp==5),"AF-09 repeat victory+2 defeat+1 retreat0 for every deployed person");
