        check(longState.level==20 && longState.exp==0 && longRun.growth.stones==30000,"AF-01/03 Lv0 to20 through completed interactions has no cap reward");AffectionRingService.Purchase(longRun);AffectionRingService.Use(longRun,home,form);for(int i=0;i<1580;i++)AffectionRewardService.Interaction(longRun,home,form,"conversation."+(i%2));
        check(longState.level==99 && longState.exp==0 && longRun.growth.stones==20000 && longRun.growth.eternalRings==0,"AF-01/04 complete Lv0->20->ring->99 progression with no additional rewards");
        check(decode(encode(longRun)).affection.states.Single(state=>state.personId==home.PersonId(form)).level==99,"AF-12 long-term Lv99 progress survives serialization");
