        var discovery=GardenLifeCatalog.Discoveries.First(d=>d.condition=="morning");var tx=new GardenDiscoveryTransaction("af.discovery",discovery.id,context);var lifeRequest=new GardenLifeRequest(tx.Id,"discovery",discovered.revision,"morning");journal=new FormalCampaignJournal(discovered,encode,decode);before=encode(journal.Snapshot);
        check(journal.CommitGardenLife(lifeRequest,home,tx.Apply,state=>false)==GrowthCommitResult.SaveFailed && encode(journal.Snapshot)==before,"AF-11 discovery and participant EXP both remain unpublished on failure");
